}

schemas.schema-07-logs.prisma:
/// Audit Trail Log – This implements the 'auditing and accountability' requirement from the Non-Functional Requirements and Technical Overview document.
///
/// Captures critical, immutable events related to user actions, moderation activity, and sensitive system changes. Maintains 3NF normalization by storing only atomic event details; connects to user, role, or topic via foreign keys where necessary. Ensures a transparent and traceable system for dispute resolution and compliance.
///
/// Usage Example: Records every post deletion, role change, login, or moderation intervention along with timestamps and linking actors.
///
/// Key relationships: References users (admins, moderators, members), posts, topics as foreign keys and does not duplicate business data.
/// Special behaviors: Entries are immutable for integrity. Acts as the single source of truth for accountability.
///
/// @namespace Logs
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_audit_trails {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each audit log entry.
  id String @id @db.Uuid

  /// Actor's {@link discussion_board_user_profiles.id} who performed the action. Needed for tracing origin of action.
  actor_id String @db.Uuid

  /// Type of action performed (e.g., create, update, delete, login, moderation). Implements the event requirement for audit. Atomic string for action identifier.
  action_type String

  /// Table/entity affected by the action. Implements target traceability requirement. E.g., 'discussion_board_posts', 'discussion_board_topics'. Maintains normalization by using reference strings, not duplicating schema details.
  target_table String

  /// ID of entity affected by the action (e.g., post, topic, user). Business meaning: enables precise accountability without duplication.
  target_id String @db.Uuid

  /// Textual description giving context to the event, such as before/after values or moderator rationale. Maintains normalization by being strictly contextual. For example, 'Changed topic status from open to closed.'
  details String?

  /// Timestamp when the audit entry was created. Implements chronological trace for auditing. Required for all logs.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_audit_trails_actor_id discussion_board_user_profiles @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([created_at])
  @@index([actor_id, created_at])
  @@index([target_table, target_id])
  @@index([details(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Action History Log – Fulfils the need for chronological, user-level action histories referenced in the Non-Functional Requirements. Stores a complete timeline of meaningful, non-sensitive user actions for usability and behavior analytics. 3NF compliance is preserved through separation from business entities, with references handled through foreign keys.
///
/// Usage Example: Shows the last 100 actions taken by a moderator or tracks a member's contribution over time. Enables better support and dispute resolution.
///
/// Key relationships: Links to user ({@link discussion_board_user_profiles}), references target table/entity, and preserves event sequences with timestamps.
/// Special behaviors: Not immutable; can be pruned/cleaned for storage optimization, but raw business data is never stored here.
///
/// @namespace Logs
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_action_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique action history entry identifier.
  id String @id @db.Uuid

  /// Actor's {@link discussion_board_user_profiles.id} who performed the action. Enables tracing user contributions and behavior analytics.
  actor_id String @db.Uuid

  /// Type of user action (e.g., post_created, post_edited, report_submitted, topic_subscribed). Implements requirement for granular activity tracking. Ensures only atomic identifiers are stored.
  action_type String

  /// Table/entity associated with the action (e.g., 'discussion_board_posts', 'discussion_board_topics', etc). Enables normalized linking to actions. Enforces normalization by reference only.
  target_table String

  /// ID of the entity acted upon (e.g., the particular topic, post, or report). Atomic linkage, not duplicating main data.
  target_id String @db.Uuid

  /// Short textual summary for easy human reading, e.g., 'User flagged post as spam'. Implements quick-read analytic requirement. Maintains normalization by only serving as metadata.
  summary String?

  /// Timestamp when the action occurred. Enables temporal analysis. Required for ordering action history.
  occurred_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_action_histories_actor_id discussion_board_user_profiles @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([occurred_at])
  @@index([actor_id, occurred_at])
  @@index([target_table, target_id])
  @@index([summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

